import math

def check_n(n):
    """
    Checks if for all 1 <= k < n such that gcd(k, n) = 1, we have k^2 - 1 divisible by n.
    """
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            if (k*k - 1) % n != 0:
                return False
    return True

solutions = []
for n in range(2, 31):
    if check_n(n):
        solutions.append(n)

print("Solutions found:", solutions)

