import math

def check_condition(n):
    """
    Checks if for any positive integer k relatively prime to n, k^2 - 1 is a multiple of n.
    We check k from 1 to n-1, as k=n is equivalent to k=0 (and gcd(n,n)=n != 1 for n>1).
    """
    if n <= 1:
        return False, "n must be >= 2"

    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check if k^2 - 1 is divisible by n
            if (k**2 - 1) % n != 0:
                return False, k
    return True, None

test_values = [5, 7, 10, 16, 20, 30]
failures = {}

print("--- Testing candidate values outside the 2^a 3^b structure ---")
for n in test_values:
    is_satisfied, failing_k = check_condition(n)

    if is_satisfied:
        print(f"Test failed: n={n} surprisingly satisfies the condition.")
    else:
        failures[n] = failing_k
        print(f"Test passed (Fails condition): n={n} fails for k={failing_k}.")

print("\n--- Summary of Failures ---")
if failures:
    for n, k in failures.items():
        print(f"n = {n} fails because k = {k} yields {k}^2 - 1 = {k**2 - 1}, which is not divisible by {n}.")
else:
    print("No failures found among the specified test values.")
